use system.collections.list
use system.collections.map
use system.fs
use system.os

// Drops one trailing carriage return so CRLF files read the same as LF files.
fn trim_cr(line String) String
    if line.ends_with("\r")
        return line.substring(0, line.size() - 1)
    line

// Splits a line on spaces, ignoring empty pieces from repeated spaces.
fn tokens(line String) List<String>
    var out = List<String>()
    for part in line.split(" ")
        if part.length() > 0
            out.push(part)
    out

// Adds one record to its key's running total. A key whose running total would
// leave the signed 64-bit range is marked broken and never changes again.
